L["In this zone by the roster, no position (%d)"] = "Dans cette zone selon la liste, sans position (%d)"
L["OpenMap draws guildmates too: type /openmap and, on its \"On the map\" tab, turn off \"Guild members on the map\"."] = "OpenMap affiche aussi la guilde : tapez /openmap et, dans l'onglet « Sur la carte », désactivez « Membres de guilde sur la carte »."
L["Only guildmates who share their position (with Guild OS, or OpenMap's sharing), and your group, show here."] = "Seuls les membres qui partagent leur position (avec Guild OS ou le partage d'OpenMap) et votre groupe apparaissent ici."
L["OpenMap shows guildmates too"] = "OpenMap affiche aussi la guilde"
L["Got it"] = "Compris"
L["Don't show again"] = "Ne plus afficher"
L["OpenMap also draws guild members on the world map, so a guildmate can show twice. Guild OS already shows the guildmates who share their place through OpenMap. To see each once, type /openmap and, on the \"On the map\" tab, turn off \"Guild members on the map\"."] = "OpenMap affiche aussi les membres de guilde sur la carte du monde : un membre peut donc apparaître deux fois. Guild OS affiche déjà ceux qui partagent leur position via OpenMap. Pour voir chacun une seule fois, tapez /openmap et, dans l'onglet « Sur la carte », désactivez « Membres de guilde sur la carte »."
L["OpenMap's \"Share where you are\" (its \"More\" tab) sends your place to the guild every few seconds even when nobody looks; Guild OS already shares it while a guildmate has the map open. Keep it on only for friends outside the guild."] = "« Partager votre position » d'OpenMap (onglet « Plus ») envoie votre position à la guilde toutes les quelques secondes, même si personne ne regarde ; Guild OS la partage déjà quand un membre a la carte ouverte. Ne le laissez activé que pour des amis hors de la guilde."
