L["Install Warmth to see the circle and build your own"] = "Installez Warmth pour voir le cercle et monter le vôtre"
L["Let the network know when you light a campfire? Other players see the campfire on the map (with Warmth). Only the campfire and your name; you can change it in the settings."] = "Prévenir le réseau quand vous allumez un feu de camp ? Les autres joueurs voient le feu sur la carte (avec Warmth). Seulement le feu et votre nom ; vous pouvez changer cela dans les options."
L["Announce my campfires to the network"] = "Annoncer mes feux de camp au réseau"
L["Guild OS memory: %.1f MB, %.1f MB after a full garbage collection."] = "Mémoire de Guild OS : %.1f Mo, %.1f Mo après un ramasse-miettes complet."
L["The game does not report addon memory on this client."] = "Le jeu n'indique pas la mémoire des addons sur ce client."
L["Frames Guild OS made this session: %d (the game never frees a frame)."] = "Cadres créés par Guild OS pendant cette session : %d (le jeu ne libère jamais un cadre)."
L["Saved data of this guild: %d members, %d recipe lists, %d professions, %d in the member history, %d roster log lines, %d raid sessions, %d loot records."] = "Données enregistrées de cette guilde : %d membres, %d listes de recettes, %d métiers, %d dans l'historique des membres, %d lignes du journal des membres, %d sessions de raid, %d butins enregistrés."
L["Guild databases in the saved variables: %d."] = "Bases de données de guilde dans les variables sauvegardées : %d."
L["Your campfire shows on the map for guildmates and players with Warmth (anonymous outside your guild and group). To turn it off: /gos campfire off"] = "Votre feu de camp apparaît sur la carte pour les membres de votre guilde et les joueurs qui ont Warmth (anonyme hors de votre guilde et de votre groupe). Pour le désactiver : /gos campfire off"
L["Announce my campfires"] = "Annoncer mes feux de camp"
L["Also to the whole realm, without my name"] = "Aussi à tout le royaume, sans mon nom"
L["Off by default on PvP realms."] = "Désactivé par défaut sur les royaumes JcJ."
