L["Campfire announce: off."] = "Annonce des feux de camp : désactivée."
L["Whole realm, without your name: on."] = "Tout le royaume, sans votre nom : activé."
L["Whole realm, without your name: off."] = "Tout le royaume, sans votre nom : désactivé."
